"""CPU-only HTTP mock API. Never pretends that a mock output was generated by Qwen."""
from __future__ import annotations

import os
import time
import uuid
from typing import Literal

from fastapi import FastAPI, File, Form, HTTPException, UploadFile
from pydantic import BaseModel, Field

BACKEND = os.getenv("QWEN38_BACKEND", "mock")
if BACKEND != "mock":
    raise RuntimeError("Only mock backend is implemented; TPU MaxEngine adapter requires separate acceptance")

app = FastAPI(title="Qwen3.8-27B TPU Showcase API", version="0.1.0",
              description="CPU development API; all generated answers are explicitly mock.")

class Message(BaseModel):
    role: Literal["system", "user", "assistant"]
    content: str = Field(min_length=1, max_length=16000)

class CompletionRequest(BaseModel):
    model: str = "qwen3.8-27b"
    messages: list[Message] = Field(min_length=1, max_length=32)
    max_tokens: int = Field(default=128, ge=1, le=512)
    temperature: float = Field(default=0.0, ge=0, le=2)

def mock_reply(content: str) -> str:
    return ("[MOCK — NOT MODEL INFERENCE] Received text: " + content[:300])

@app.get("/health")
def health():
    return {"status": "ok", "backend": BACKEND, "model_loaded": False, "inference_available": False}

@app.get("/metrics")
def metrics():
    return {"backend": BACKEND, "model_load_count": 0, "is_tpu": False,
            "real_inference_requests": 0, "note": "CPU mock only"}

@app.post("/v1/chat/completions")
def chat(req: CompletionRequest):
    prompt = next((m.content for m in reversed(req.messages) if m.role == "user"), None)
    if not prompt:
        raise HTTPException(status_code=422, detail="A user message is required")
    now = int(time.time())
    return {"id": "mock-" + uuid.uuid4().hex, "object": "chat.completion", "created": now,
            "model": req.model, "backend": BACKEND, "mock": True,
            "choices": [{"index": 0, "message": {"role": "assistant", "content": mock_reply(prompt)}, "finish_reason": "stop"}],
            "usage": {"prompt_tokens": None, "completion_tokens": None, "total_tokens": None}}

@app.post("/v1/vision/analyze")
async def vision(image: UploadFile = File(...), prompt: str = Form(...)):
    if not prompt.strip():
        raise HTTPException(status_code=422, detail="Prompt must not be blank")
    content_type = image.content_type or ""
    if content_type not in ("image/png", "image/jpeg", "image/webp"):
        raise HTTPException(status_code=415, detail="Only PNG, JPEG and WebP are supported")
    size = 0
    header = bytearray()
    while chunk := await image.read(1024 * 1024):
        size += len(chunk)
        if len(header) < 16:
            header.extend(chunk[:16-len(header)])
        if size > 8 * 1024 * 1024:
            raise HTTPException(status_code=413, detail="Image exceeds 8 MiB")
    if not size:
        raise HTTPException(status_code=422, detail="Image is empty")
    signature = (content_type == "image/png" and header.startswith(b"\x89PNG\r\n\x1a\n")) or (
        content_type == "image/jpeg" and header.startswith(b"\xff\xd8\xff")) or (
        content_type == "image/webp" and header[:4] == b"RIFF" and header[8:12] == b"WEBP")
    if not signature:
        raise HTTPException(status_code=422, detail="Image signature does not match MIME type")
    return {"id": "mock-" + uuid.uuid4().hex, "backend": BACKEND, "mock": True,
            "filename": image.filename, "bytes_received": size, "content_type": content_type,
            "prompt": prompt, "answer": "[MOCK — NOT VISION INFERENCE] Image uploaded successfully. No model was run."}
